3826	// ===========================================================================
3827	// AUTOMATIC TLS
3828	// ===========================================================================
3829	/**
3830	 * "Migrate → point DNS → it just works" has to include HTTPS, or the customer's
3831	 * first visit is a browser certificate warning. Three layers, tried in order,
3832	 * and honest at every rung:
3833	 *
3834	 *   1. MIGRATED CERTIFICATES. Let's Encrypt certificates are portable — they
3835	 *      stay valid on whichever machine serves them — so copying /etc/letsencrypt
3836	 *      (certs, keys, `renewal/*.conf`, `accounts/`, the ssl option snippets)
3837	 *      gives zero-gap HTTPS the instant traffic moves. Step 8d does the copy;
3838	 *      fixRenewalConfigs repoints renewal at THIS server's webroot so
3839	 *      `certbot renew` keeps working afterwards.
3840	 *
3841	 *   2. HTTP-01 per hostname. This can only succeed once the name resolves HERE,
3842	 *      so it runs for names that already point at us, and is exposed as
3843	 *      `issueMigrationCertificates()` for the DNS-cutover flow to call again
3844	 *      afterwards. Every generated vhost carries a
3845	 *      `location ^~ /.well-known/acme-challenge/` so `--webroot` validates.
3846	 *
3847	 *   3. DNS-01 for wildcards, through the customer's connected Cloudflare
3848	 *      account. Multi-tenant apps serve `<tenant>.<base>` and HTTP-01 simply
3849	 *      cannot issue `*.base`. The token is passed IN by the caller (it lives on
3850	 *      the Nxeon side, not on the customer's box), written to a 0600 credentials
3851	 *      file over SFTP — never an argv token — and shredded in `finally`.
3852	 *      Note a wildcard covers exactly ONE label, so `hq.stg.example.com` needs
3853	 *      `*.stg.example.com` as well as `*.example.com`; both are requested.
3854	 *
3855	 * A certificate failure NEVER fails the migration — it becomes a named,
3856	 * copy-pasteable manual step.
3857	 */
3858	const EMAIL_RE = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$/;
3859	const ACME_WEBROOT = "/var/www/html";
3860	
3861	/** What this migration published, persisted so the cutover flow can re-secure it. */
3862	type SiteSpec = { sites: TargetSite[]; bindIp: string; http2: boolean; kind: "nginx" | "apache" };
3863	
3864	/**
3865	 * Re-validate a SiteSpec read back off the target. It is our own JSON, but it
3866	 * came off a machine, so every field goes through the same allowlists again
3867	 * before it can reach a config file or a command.
3868	 */
3869	function sanitizeSiteSpec(raw: unknown): SiteSpec | null {
3870	  const r = raw as Record<string, unknown> | null;
3871	  if (!r || typeof r !== "object") return null;
3872	  const bindIp = typeof r.bindIp === "string" && IPV4_RE.test(r.bindIp) ? r.bindIp : "";
3873	  const kind: "nginx" | "apache" = r.kind === "apache" ? "apache" : "nginx";
3874	  const sites: TargetSite[] = [];
3875	  for (const s of (Array.isArray(r.sites) ? r.sites : []).slice(0, 20) as Record<string, unknown>[]) {
3876	    const names = (Array.isArray(s?.names) ? (s.names as unknown[]) : [])
3877	      .map((n) => normalizeDomain(String(n ?? "")))
3878	      .filter((n): n is string => !!n)
3879	      .slice(0, 12);
3880	    if (!names.length) continue;
3881	    const portNum = Number(s?.proxyPort);
3882	    const proxyPort = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535 ? portNum : 0;
3883	    const root = typeof s?.root === "string" && validPath(s.root) ? s.root : "";
3884	    if (!proxyPort && !root) continue;
3885	    sites.push({
3886	      names,
3887	      wildcard: normalizeDomain(String(s?.wildcard ?? "")) ?? "",
3888	      proxyPort,
3889	      root,
3890	      certDomain: normalizeDomain(String(s?.certDomain ?? "")) ?? "",
3891	      phpSocket: typeof s?.phpSocket === "string" && validPath(s.phpSocket) ? s.phpSocket : "",
3892	    });
3893	  }
3894	  return sites.length ? { sites, bindIp, http2: !!r.http2, kind } : null;
3895	}
3896	
3897	async function readSiteSpec(conn: Client, work: string): Promise<SiteSpec | null> {
3898	  const r = await sh(conn, `cat ${work}/sites.json 2>/dev/null`);
3899	  if (r.code !== 0 || !r.stdout.trim()) return null;
3900	  try {
3901	    return sanitizeSiteSpec(JSON.parse(r.stdout));
3902	  } catch {
3903	    return null;
3904	  }
3905	}
