3907	/** True when a live certificate + key really exist here for this exact name. */
3908	async function certExists(conn: Client, domain: string): Promise<boolean> {
3909	  if (!DOMAIN_RE.test(domain)) return false;
3910	  return shOk(conn, `test -s /etc/letsencrypt/live/${domain}/fullchain.pem && test -s /etc/letsencrypt/live/${domain}/privkey.pem`);
3911	}
3912	
3913	/** Does this hostname already resolve to the NEW server? HTTP-01 requires it. */
3914	async function resolvesHere(conn: Client, domain: string, ip: string): Promise<boolean> {
3915	  if (!DOMAIN_RE.test(domain) || !IPV4_RE.test(ip)) return false;
3916	  const r = await sh(conn, `getent ahostsv4 ${domain} 2>/dev/null | awk '{print $1}' | sort -u | head -n 8`);
3917	  // cleanLines, NOT clean: `clean` strips the newlines this output is split on, so
3918	  // every A record collapsed into one string and `.includes(ip)` was ALWAYS false.
3919	  // A domain correctly pointed at the new server was reported as not pointing
3920	  // there, which blocks HTTP-01 and makes certificate issuance unreachable.
3921	  return cleanLines(r.stdout, 512).split("\n").map((s) => s.trim()).includes(ip);
3922	}
3923	
3924	async function ensureAcmeWebroot(conn: Client): Promise<void> {
3925	  await sh(conn, `mkdir -p ${ACME_WEBROOT}/.well-known/acme-challenge && chmod -R 755 ${ACME_WEBROOT}/.well-known`);
3926	}
3927	
3928	/**
3929	 * Repoint migrated renewal profiles at THIS server. Without this, `certbot renew`
3930	 * keeps trying the old server's webroot (or its nginx/apache installer) and the
3931	 * migrated certificates quietly stop renewing about 60 days later. DNS-01
3932	 * profiles are left alone — their authenticator is already host-independent.
3933	 */
3934	export const RENEWAL_FIX_SCRIPT = [
3935	  "n=0",
3936	  "for f in /etc/letsencrypt/renewal/*.conf; do",
3937	  '  [ -f "$f" ] || continue',
3938	  "  if grep -qE '^authenticator[[:space:]]*=[[:space:]]*dns' \"$f\"; then continue; fi",
3939	  "  sed -i -e 's|^authenticator[[:space:]]*=.*|authenticator = webroot|' " +
3940	    "-e 's|^installer[[:space:]]*=.*|installer = None|' " +
3941	    "-e 's|^webroot_path[[:space:]]*=.*|webroot_path = /var/www/html,|' \"$f\"",
3942	  "  awk 'BEGIN{m=0} /^\\[\\[webroot_map\\]\\]/{print; m=1; next} m==1 && /=/{sub(/=.*/, \"= /var/www/html\"); print; next} {print}' \"$f\" > \"$f.nx\" 2>/dev/null && mv \"$f.nx\" \"$f\"",
3943	  "  grep -q '^webroot_path' \"$f\" || printf 'webroot_path = /var/www/html,\\n' >> \"$f\"",
3944	  "  n=$((n+1))",
3945	  "done",
3946	  "printf 'RENEWALFIX %s\\n' \"$n\"",
3947	  "",
3948	].join("\n");
3949	
3950	async function fixRenewalConfigs(conn: Client, sftp: SFTPWrapper, work: string): Promise<number> {
3951	  const p = `${work}/fix-renewal.sh`;
3952	  await sftpWrite(sftp, p, RENEWAL_FIX_SCRIPT).catch(() => {});
3953	  const r = await sh(conn, `sh ${p} 2>/dev/null`, SETUP_TIMEOUT_MS);
3954	  const m = /RENEWALFIX\s+(\d+)/.exec(r.stdout);
3955	  return m ? Number(m[1]) : 0;
3956	}
