3958	/** The `-m …` / `--register-unsafely-without-email` fragment (validated email only). */
3959	export function acmeAccountArgs(email: string): string {
3960	  return email && EMAIL_RE.test(email) ? `-m ${email} --no-eff-email` : "--register-unsafely-without-email";
3961	}
3962	
3963	/** HTTP-01 via webroot. `certName` fixes the /etc/letsencrypt/live/<name> directory. */
3964	async function issueHttp01(conn: Client, certName: string, domains: string[], email: string): Promise<{ ok: boolean; err: string }> {
3965	  const ds = [...new Set(domains.filter((d) => DOMAIN_RE.test(d)))].slice(0, 20);
3966	  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
3967	  const cmd =
3968	    `certbot certonly --webroot -w ${ACME_WEBROOT} -n --agree-tos ${acmeAccountArgs(email)} ` +
3969	    `--keep-until-expiring --cert-name ${certName} ${ds.map((d) => `-d ${d}`).join(" ")} 2>&1`;
3970	  const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
3971	  if (await certExists(conn, certName)) return { ok: true, err: "" };
3972	  return { ok: false, err: tailOf(r, 2, 220) };
3973	}
3974	
3975	/**
3976	 * DNS-01 via the customer's connected Cloudflare account — the only way to get a
3977	 * wildcard. The token never appears in argv: it is written to a 0600 credentials
3978	 * file over SFTP and shredded immediately afterwards, success or failure.
3979	 */
3980	async function issueDns01(
3981	  conn: Client,
3982	  sftp: SFTPWrapper,
3983	  work: string,
3984	  token: string,
3985	  certName: string,
3986	  domains: string[],
3987	  email: string
3988	): Promise<{ ok: boolean; err: string }> {
3989	  if (!token || token.length > 512 || /[\r\n]/.test(token)) return { ok: false, err: "unusable Cloudflare token" };
3990	  const ds = [...new Set(domains)].filter((d) => DOMAIN_RE.test(d.replace(/^\*\./, ""))).slice(0, 20);
3991	  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
3992	  const ini = `${work}/cf-dns.ini`;
3993	  try {
3994	    await sftpWrite(sftp, ini, `dns_cloudflare_api_token = ${token}\n`);
3995	    await sh(conn, `chmod 600 ${ini}`);
3996	    const cmd =
3997	      `certbot certonly --dns-cloudflare --dns-cloudflare-credentials ${ini} --dns-cloudflare-propagation-seconds 45 ` +
3998	      `-n --agree-tos ${acmeAccountArgs(email)} --keep-until-expiring --cert-name ${certName} ` +
3999	      `${ds.map((d) => `-d '${d}'`).join(" ")} 2>&1`;
4000	    const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
4001	    if (await certExists(conn, certName)) return { ok: true, err: "" };
4002	    return { ok: false, err: tailOf(r, 2, 220) };
4003	  } finally {
4004	    await sh(conn, `shred -u ${ini} 2>/dev/null || rm -f ${ini}`).catch(() => {});
4005	  }
4006	}
4007	
4008	/**
4009	 * A wildcard covers exactly ONE label, so a multi-tenant app that also has a
4010	 * staging tier (`hq.stg.example.com`) needs `*.stg.example.com` as well as
4011	 * `*.example.com`. Return every base that needs its own wildcard.
4012	 */
4013	export function wildcardBasesFor(site: TargetSite): string[] {
4014	  const bases = new Set<string>();
4015	  if (site.wildcard) bases.add(site.wildcard);
4016	  for (const n of site.names) {
4017	    const parts = n.split(".");
4018	    if (parts.length < 3) continue;
4019	    const parent = parts.slice(1).join(".");
4020	    if (site.wildcard && parent !== site.wildcard && parent.endsWith(`.${site.wildcard}`)) bases.add(parent);
4021	  }
4022	  return [...bases].slice(0, 4);
4023	}
