4025	/** Rewrite + reload the generated config so newly-issued certs are actually used. */
4026	async function applyCertsAndReload(
4027	  conn: Client,
4028	  sftp: SFTPWrapper,
4029	  work: string,
4030	  spec: SiteSpec
4031	): Promise<{ ok: boolean; detail: string }> {
4032	  for (const s of spec.sites) {
4033	    s.certDomain = "";
4034	    for (const n of s.names) {
4035	      if (await certExists(conn, n)) {
4036	        s.certDomain = n;
4037	        break;
4038	      }
4039	    }
4040	  }
4041	  const conf =
4042	    spec.kind === "apache"
4043	      ? buildMigratedApacheConf(spec.sites, spec.bindIp)
4044	      : buildMigratedNginxConf(spec.sites, spec.bindIp, spec.http2);
4045	  await sftpWrite(sftp, `${work}/sites.json`, JSON.stringify(spec)).catch(() => {});
4046	  if (spec.kind === "apache") {
4047	    const site = `/etc/apache2/sites-available/nxeon-migrated.conf`;
4048	    await sftpWrite(sftp, site, conf);
4049	    await sh(conn, `chmod 644 ${site}`);
4050	    const t = await sh(conn, `apachectl configtest 2>&1`);
4051	    if (t.code !== 0) return { ok: false, detail: `Apache rejected the updated config: ${tailOf(t, 1, 160)}` };
4052	    await sh(conn, `systemctl restart apache2 2>&1`, SETUP_TIMEOUT_MS);
4053	    return { ok: clean((await sh(conn, `systemctl is-active apache2`)).stdout, 32) === "active", detail: "Apache restarted with the certificates" };
4054	  }
4055	  const primary = (await shOk(conn, `test -f /etc/nginx/conf.d/nxeon-migrated.conf`))
4056	    ? `/etc/nginx/conf.d/nxeon-migrated.conf`
4057	    : `/etc/nginx/sites-available/nxeon-migrated.conf`;
4058	  await sftpWrite(sftp, primary, conf);
4059	  await sh(conn, `chmod 644 ${primary}`);
4060	  const t = await sh(conn, `nginx -t 2>&1`);
4061	  if (t.code !== 0) return { ok: false, detail: `nginx rejected the updated config: ${tailOf(t, 1, 160)}` };
4062	  await sh(conn, `systemctl restart nginx 2>&1`, SETUP_TIMEOUT_MS);
4063	  return { ok: clean((await sh(conn, `systemctl is-active nginx`)).stdout, 32) === "active", detail: "nginx restarted with the certificates" };
4064	}
4065	
4066	export type TlsPending = PendingItem;
4067	
4068	/**
4069	 * Walk the fallback ladder for every published site and report, per hostname,
4070	 * whether it now has TLS: migrated certificate → DNS-01 wildcard (when
4071	 * Cloudflare is connected) → HTTP-01 → a named manual command.
4072	 */
4073	async function secureSites(opts: {
4074	  conn: Client;
4075	  sftp: SFTPWrapper;
4076	  work: string;
4077	  spec: SiteSpec;
4078	  targetIp: string;
4079	  email: string;
4080	  cloudflareToken?: string | null;
4081	  webOwnedByContainer: boolean;
4082	  say: (line: string) => Promise<void>;
4083	}): Promise<{ secured: string[]; pending: TlsPending[] }> {
4084	  const { conn, sftp, work, spec, targetIp, email, cloudflareToken, webOwnedByContainer, say } = opts;
4085	  const secured: string[] = [];
4086	  const pending: TlsPending[] = [];
4087	
4088	  await ensureAcmeWebroot(conn);
4089	  const fixed = await fixRenewalConfigs(conn, sftp, work);
4090	  if (fixed) await say(`  Repointed ${fixed} certificate renewal profile(s) at this server so they keep auto-renewing.`);
4091	
4092	  let needCertbot = false;
4093	  for (const s of spec.sites) for (const n of s.names) if (!(await certExists(conn, n))) needCertbot = true;
4094	  if (needCertbot) {
4095	    const wantCf = !!cloudflareToken && spec.sites.some((s) => s.wildcard);
4096	    // `say` is threaded in so the install narrates itself: this exact call is
4097	    // what sat silent for ten minutes at 89% on 2026-07-25.
4098	    await ensurePackages(conn, wantCf ? ["certbot", "certbot_dns_cloudflare"] : ["certbot"], say);
4099	  }
4100	
4101	  for (const site of spec.sites) {
4102	    // 1. Already covered by a certificate that came across with the migration.
4103	    let covered = false;
4104	    for (const n of site.names) {
4105	      if (await certExists(conn, n)) {
4106	        secured.push(...site.names);
4107	        await say(`  ${n}: HTTPS already covered by the certificate migrated from the old server.`);
4108	        covered = true;
4109	        break;
4110	      }
4111	    }
4112	    if (covered) continue;
4113	
4114	    // 3. Wildcard via DNS-01 — the ONLY way to get `*.domain`.
4115	    const bases = wildcardBasesFor(site);
4116	    if (bases.length && cloudflareToken) {
4117	      let anyOk = false;
4118	      for (const base of bases) {
4119	        // DNS-01 waits 45s for propagation before it even asks the CA, so it is
4120	        // always a multi-minute step — it narrates itself.
4121	        const r = await withHeartbeat(`issuing the wildcard certificate for *.${base} (waiting for DNS to propagate)`, say, () =>
4122	          issueDns01(conn, sftp, work, cloudflareToken, base, [`*.${base}`, base], email)
4123	        );
4124	        if (r.ok) {
4125	          anyOk = true;
4126	          secured.push(base, `*.${base}`);
4127	          await say(`  Issued a wildcard certificate for *.${base} through your connected Cloudflare account (DNS-01).`);
4128	        } else {
4129	          pending.push({
4130	            domain: `*.${base}`,
4131	            why: `the wildcard certificate could not be issued (${r.err || "unknown error"})`,
4132	            fix: `certbot certonly --dns-cloudflare --dns-cloudflare-credentials <cloudflare.ini> -d '*.${base}' -d ${base}`,
4133	          });
4134	        }
4135	      }
4136	      if (anyOk) continue;
4137	    } else if (bases.length) {
4138	      pending.push({
4139	        domain: `*.${bases[0]}`,
4140	        why:
4141	          "this app gives each tenant its own subdomain, which needs a wildcard certificate — and a wildcard can only be issued with a DNS-01 challenge. Connect Cloudflare in Settings and we can issue it for you automatically",
4142	        fix: `certbot certonly --manual --preferred-challenges dns -d '*.${bases[0]}' -d ${bases[0]}`,
4143	      });
4144	    }
4145	
4146	    // 2. HTTP-01 for the names that already point at this server.
4147	    if (webOwnedByContainer) {
4148	      pending.push({
4149	        domain: site.names[0],
4150	        why: "port 80 is served by one of your containers, so the certificate check cannot run on the host",
4151	        fix: `issue TLS inside your proxy container (Traefik and Caddy do this automatically once ${site.names[0]} resolves here)`,
4152	      });
4153	      continue;
4154	    }
4155	    const resolving: string[] = [];
4156	    for (const n of site.names) if (await resolvesHere(conn, n, targetIp)) resolving.push(n);
4157	    if (!resolving.length) {
4158	      pending.push({
4159	        domain: site.names[0],
4160	        why: `${site.names.length > 1 ? "none of these names point" : "this name does not point"} at the new server yet${targetIp ? ` (${targetIp})` : ""}, and a certificate cannot be issued until DNS moves`,
4161	        // NOT "point the DNS, then run certbot". The old wording deadlocked
4162	        // against the end-of-run warning ("do not move DNS for these names yet"):
4163	        // the certificate needs DNS to move, and the summary told the customer not
4164	        // to move DNS. There IS a correct order and it is the only thing that
4165	        // needed saying — the site is already verified over HTTP on this server
4166	        // with a Host header, so moving DNS is the NEXT STEP, not a hazard, and
4167	        // Nxeon issues the certificate itself within half an hour of the move.
4168	        fix:
4169	          `this site is already serving over HTTP on this server, so move its DNS to ${targetIp || "this server"} now — Nxeon issues the ` +
4170	          `certificate automatically within about 30 minutes of the change, and nothing else is needed. To do it immediately instead: ` +
4171	          `certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${site.names[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
4172	      });
4173	      continue;
4174	    }
4175	    const r = await withHeartbeat(`requesting the certificate for ${resolving.slice(0, 3).join(", ")}`, say, () =>
4176	      issueHttp01(conn, resolving[0], resolving, email)
4177	    );
4178	    if (r.ok) {
4179	      secured.push(...resolving);
4180	      await say(`  Issued a certificate for ${resolving.join(", ")}.`);
4181	      const notYet = site.names.filter((n) => !resolving.includes(n));
4182	      if (notYet.length) {
4183	        pending.push({
4184	          domain: notYet[0],
4185	          why: `${notYet.join(", ")} ${notYet.length > 1 ? "do" : "does"} not point at the new server yet, so ${notYet.length > 1 ? "they were" : "it was"} left out of the certificate`,
4186	          fix:
4187	            `move the DNS for ${notYet.join(", ")} to ${targetIp || "this server"} — Nxeon adds ${notYet.length > 1 ? "them" : "it"} to the ` +
4188	            `certificate automatically within about 30 minutes. To do it immediately instead: ` +
4189	            `certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
4190	        });
4191	      }
4192	    } else {
4193	      pending.push({
4194	        domain: resolving[0],
4195	        why: `the certificate request failed (${r.err || "unknown error"})`,
4196	        fix: `certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${resolving.map((d) => `-d ${d}`).join(" ")}`,
4197	      });
4198	    }
4199	  }
4200	
4201	  if (secured.length) {
4202	    const applied = await applyCertsAndReload(conn, sftp, work, spec);
4203	    if (!applied.ok) {
4204	      pending.push({
4205	        domain: spec.sites[0]?.names[0] ?? "",
4206	        why: `certificates were issued but the web server would not take the updated config (${applied.detail})`,
4207	        fix: "check `nginx -t` / `apachectl configtest` on the server",
4208	      });
4209	    }
4210	  }
4211	  return { secured: [...new Set(secured)], pending };
4212	}
