4214	export type MigrationTlsInput = {
4215	  target: TargetServer | null;
4216	  migrationId: string;
4217	  /** Hostnames beyond the ones the migration published (e.g. the customer's Domain rows). */
4218	  extraDomains?: string[];
4219	  /** A Cloudflare API token with DNS-edit scope, resolved on the Nxeon side. */
4220	  cloudflareToken?: string | null;
4221	  acmeEmail?: string | null;
4222	  report?: ReportFn;
4223	};
4224	export type MigrationTlsResult = {
4225	  secured: string[];
4226	  pending: TlsPending[];
4227	  error?: string;
4228	  /**
4229	   * True when `error` describes a condition that CANNOT resolve itself with time
4230	   * — the caller should stop retrying rather than treat it as a transient fault.
4231	   * An error we retry forever is an error we notify the customer about forever.
4232	   */
4233	  permanent?: boolean;
4234	};
4235	
4236	/**
4237	 * Issue/refresh TLS for a completed migration — the step that must run AFTER DNS
4238	 * is pointed, because HTTP-01 cannot validate a name that still resolves to the
4239	 * old server.
4240	 *
