1694	/**
1695	 * Make one image exist on the TARGET.
1696	 *
1697	 *   already present → nothing (a re-run must not re-transfer gigabytes)
1698	 *   public registry → `docker pull` (fast, and costs no source bandwidth)
1699	 *   otherwise       → `docker save | gzip` on the source, streamed straight
1700	 *                     through the SSH channel into `gunzip | docker load`
1701	 *
1702	 * The locally-built case is the one that silently broke a real migration: the
1703	 * engine copied files and named volumes but never the IMAGE, so standalone
1704	 * containers could never start. A pull that fails also falls back to save/load,
1705	 * so a private registry the new box cannot authenticate to still works.
1706	 *
1707	 * `ref` is validated by validImageRef before it reaches any command; success is
1708	 * confirmed with `docker image inspect` rather than trusting an exit code
1709	 * through a pipeline.
1710	 */
1711	async function ensureImage(
1712	  conn: Client,
1713	  ref: string,
1714	  local: boolean,
1715	  onSource: (cmd: string) => string,
1716	  priv: string,
1717	  say: (line: string) => Promise<void>
1718	): Promise<{ status: "present" | "pulled" | "loaded" | "failed"; detail: string }> {
1719	  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };
1720	
1721	  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1722	    return { status: "present", detail: "already on the new server" };
1723	  }
1724	
1725	  if (!local) {
1726	    // A multi-gigabyte pull is one of the three steps that can sit silent for
1727	    // minutes, so it narrates itself (see withHeartbeat).
1728	    const pull = await withHeartbeat(`downloading the container image ${ref}`, say, () =>
1729	      sh(conn, `docker pull ${ref} 2>&1`, IMAGE_TIMEOUT_MS)
1730	    );
1731	    if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1732	      return { status: "pulled", detail: "pulled from its registry" };
1733	    }
1734	    const why = tailOf(pull, 1, 120);
1735	    await say(`  ${ref}: pull failed (${why || "unavailable"}) — transferring it from the old server instead.`);
1736	  }
