1739	  // through the SSH channel we already hold. gzip -1 because these links are
1740	  // usually faster than the CPU and the layers are mostly already compressed.
1741	  const stream = `${onSource(`${priv}docker save ${ref} | gzip -1`)} | gunzip -c | docker load 2>&1`;
1742	  const r = await withHeartbeat(`transferring the container image ${ref} from the old server`, say, () =>
1743	    sh(conn, stream, IMAGE_TIMEOUT_MS)
1744	  );
1745	  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1746	    return { status: "loaded", detail: "transferred from the old server (docker save/load)" };
1747	  }
1748	  const why = tailOf(r, 2, 180);
1749	  return {
1750	    status: "failed",
1751	    detail: isEnospc(why)
1752	      ? "ran out of disk while loading the image"
1753	      : `could not pull or transfer the image${why ? `: ${why}` : ""}`,
1754	  };
